1|// Music manifest parsing. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import type {
5|  MusicManifest,
6|  Playlist,
7|  Soundtrack,
8|  Track,
9|  TrackSource,
10|} from "./music-types";
11|
12|const SUPPORTED_VERSION = 3;
13|const SOURCES = ["generated", "jamendo", "recording"] as const;
14|const SLUG = /^[a-z0-9-]+$/;
15|
16|function isRecord(value: unknown): value is Record<string, unknown> {
17|  return typeof value === "object" && value !== null && !Array.isArray(value);
18|}
19|
20|function isOneOf<T extends string>(value: unknown, allowed: readonly T[]): value is T {
21|  return typeof value === "string" && allowed.some((entry) => entry === value);
22|}
23|
24|function isVector8(value: unknown): value is Vector8 {
25|  if (!isRecord(value)) return false;
26|  return EMOTIONS.every(
27|    (id: EmotionId) =>
28|      typeof value[id] === "number" &&
29|      Number.isFinite(value[id]) &&
30|      (value[id] as number) >= 0 &&
31|      (value[id] as number) <= 1,
32|  );
33|}
34|
35|function isUnit(value: unknown): value is number {
36|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1;
37|}
38|
39|function isSrc(value: unknown): value is string {
40|  return (
41|    typeof value === "string" && (value.startsWith("/music/") || value.startsWith("https://"))
42|  );
43|}
44|
45|function isNonEmptyString(value: unknown): value is string {
46|  return typeof value === "string" && value !== "";
47|}
48|
49|// Fail loudly on a bad drop-in manifest so broken files never play quiet.
50|export function parseManifest(json: unknown): MusicManifest {
51|  if (!isRecord(json)) throw new Error("manifest must be an object");
52|  if (json.version !== 3 && json.version !== 2) {
53|    throw new Error(`unsupported manifest version: ${String(json.version)}`);
54|  }
55|  // A v2 manifest becomes one implicit soundtrack holding every track.
56|  if (json.version === 2) {
57|    if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
58|    const tracks = json.tracks.map((entry, i) => parseTrack(entry, i, "default", "orchestral"));
59|    return {
60|      version: 3,
61|      styles: [{ id: "orchestral", name: "Orchestra" }],
62|      soundtracks: [{ id: "default", name: "Default", style: "orchestral" }],
63|      tracks,
64|      playlists: [],
65|    };
66|  }
67|  if (!Array.isArray(json.styles)) throw new Error("manifest styles must be an array");
68|  if (!Array.isArray(json.soundtracks)) throw new Error("manifest soundtracks must be an array");
69|  if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
70|  const styles = json.styles.map((entry, i) => {
71|    if (!isRecord(entry)) throw new Error(`style ${i} must be an object`);
72|    if (typeof entry.id !== "string" || !SLUG.test(entry.id)) {
73|      throw new Error(`style ${i} id must be a non-empty lowercase slug`);
74|    }
75|    if (typeof entry.name !== "string" || entry.name === "") {
76|      throw new Error(`style ${entry.id} name must be a non-empty string`);
77|    }
78|    return { id: entry.id, name: entry.name };
79|  });
80|  const styleIds = new Set<string>();
81|  for (const s of styles) {
82|    if (styleIds.has(s.id)) throw new Error(`duplicate style id: ${s.id}`);
83|    styleIds.add(s.id);
84|  }
85|  const soundtracks = json.soundtracks.map((entry, i) => {
86|    if (!isRecord(entry)) throw new Error(`soundtrack ${i} must be an object`);
87|    if (typeof entry.id !== "string" || entry.id === "") {
88|      throw new Error(`soundtrack ${i} needs a non-empty string id`);
89|    }
90|    if (typeof entry.name !== "string" || entry.name === "") {
91|      throw new Error(`soundtrack ${entry.id} name must be a non-empty string`);
92|    }
93|    if (typeof entry.style !== "string" || !SLUG.test(entry.style)) {
94|      throw new Error(`soundtrack ${entry.id} style must be a non-empty lowercase slug`);
95|    }
96|    if (!styleIds.has(entry.style)) {
97|      throw new Error(`soundtrack ${entry.id} style ${entry.style} is not a listed style`);
98|    }
99|    const out: Soundtrack = { id: entry.id, name: entry.name, style: entry.style };
100|    if (entry.credit !== undefined) {
101|      if (typeof entry.credit !== "string" || entry.credit === "") {
102|        throw new Error(`soundtrack ${entry.id} credit must be a non-empty string`);
103|      }
104|      out.credit = entry.credit;
105|    }
106|    return out;
107|  });
108|  const trackSoundtracks = new Map(soundtracks.map((s) => [s.id, s.style]));
109|  const seenSoundtrack = new Set<string>();
110|  for (const s of soundtracks) {
111|    if (seenSoundtrack.has(s.id)) throw new Error(`duplicate soundtrack id: ${s.id}`);
112|    seenSoundtrack.add(s.id);
113|  }
114|  const tracks = json.tracks.map((entry, i) => {
115|    if (!isRecord(entry)) throw new Error(`track ${i} must be an object`);
116|    const soundtrack: unknown = entry.soundtrack;
117|    const style: unknown = entry.style;
118|    if (typeof soundtrack !== "string" || soundtrack === "") {
119|      throw new Error(`track ${i} needs a soundtrack id`);
120|    }
121|    const home = trackSoundtracks.get(soundtrack);
122|    if (home === undefined) {
123|      throw new Error(`track ${String(entry.id) || i} soundtrack ${soundtrack} is unknown`);
124|    }
125|    if (typeof style !== "string" || style === "") {
126|      throw new Error(`track ${String(entry.id) || i} needs a style slug`);
127|    }
128|    if (!styleIds.has(style)) {
129|      throw new Error(`track ${String(entry.id) || i} style ${style} is not a listed style`);
130|    }
131|    if (style !== home) {
132|      throw new Error(
133|        `track ${String(entry.id) || i} style ${style} differs from its soundtrack style ${home}`,
134|      );
135|    }
136|    return parseTrack(entry, i, soundtrack, style);
137|  });
138|  const seenTrack = new Set<string>();
139|  for (const t of tracks) {
140|    if (seenTrack.has(t.id)) throw new Error(`duplicate track id: ${t.id}`);
141|    seenTrack.add(t.id);
142|  }
143|  const trackIds = new Set(tracks.map((t) => t.id));
144|  return { version: SUPPORTED_VERSION, styles, soundtracks, tracks, playlists: parsePlaylists(json, trackIds) };
145|}
146|
147|// Playlists are optional; a missing key parses as an empty list. Each
148|// entry names tracks that must exist, so a typo fails loudly at load.
149|function parsePlaylists(json: Record<string, unknown>, trackIds: Set<string>): Playlist[] {
150|  if (json.playlists === undefined) return [];
151|  if (!Array.isArray(json.playlists)) throw new Error("manifest playlists must be an array");
152|  const seen = new Set<string>();
153|  return json.playlists.map((entry, i) => {
154|    if (!isRecord(entry)) throw new Error(`playlist ${i} must be an object`);
155|    const { id, label, trackIds: ids } = entry;
156|    if (typeof id !== "string" || id === "") throw new Error(`playlist ${i} needs a non-empty string id`);
157|    if (seen.has(id)) throw new Error(`duplicate playlist id: ${id}`);
158|    seen.add(id);
159|    if (typeof label !== "string" || label === "") {
160|      throw new Error(`playlist ${id} label must be a non-empty string`);
161|    }
162|    if (!Array.isArray(ids)) throw new Error(`playlist ${id} trackIds must be an array`);
163|    for (const tid of ids) {
164|      if (typeof tid !== "string" || !trackIds.has(tid)) {
165|        throw new Error(`playlist ${id} has unknown track id: ${String(tid)}`);
166|      }
167|    }
168|    return { id, label, trackIds: [...ids] as string[] };
169|  });
170|}
171|
172|function parseTrack(entry: unknown, i: number, soundtrack: string, style: string): Track {
173|  if (!isRecord(entry)) throw new Error(`track ${i} must be an object`);
174|  {
175|    const { id, src, title, emotion, vector, intensity, tempo } = entry;
176|    const { durationSec, startSec, gainDb, endSec, loop, playlistOnly } = entry;
177|    const { source, artist, composer, license, attribution, sourceUrl } = entry;
178|    if (typeof id !== "string" || id === "") throw new Error(`track ${i} needs a string id`);
179|    if (!isSrc(src)) throw new Error(`track ${id} src must be a /music/ path or https URL`);
180|    if (typeof title !== "string" || title === "") throw new Error(`track ${id} needs a title`);
181|    if (!isOneOf(emotion, EMOTIONS)) {
182|      throw new Error(`track ${id} emotion must be one of the 8 emotion ids`);
183|    }
184|    if (!isVector8(vector)) throw new Error(`track ${id} vector must cover the 8 emotion ids`);
185|    if (!isUnit(intensity)) throw new Error(`track ${id} intensity must be 0..1`);
186|    if (!isUnit(tempo)) throw new Error(`track ${id} tempo must be 0..1`);
187|    if (typeof durationSec !== "number" || !Number.isFinite(durationSec) || durationSec <= 0) {
188|      throw new Error(`track ${id} durationSec must be a positive number`);
189|    }
190|    let start = 0;
191|    if (startSec !== undefined) {
192|      if (typeof startSec !== "number" || !Number.isFinite(startSec) || startSec < 0) {
193|        throw new Error(`track ${id} startSec must be >= 0`);
194|      }
195|      // No upper bound here: startSec is an absolute media position while
196|      // durationSec is the playable length, so mid-file segments can start
197|      // past it. The endSec check below bounds the segment instead.
198|      start = startSec;
199|    }
200|    let gain = 0;
201|    if (gainDb !== undefined) {
202|      if (typeof gainDb !== "number" || !Number.isFinite(gainDb) || gainDb < -24 || gainDb > 12) {
203|        throw new Error(`track ${id} gainDb must be a finite number in -24..12`);
204|      }
205|      gain = gainDb;
206|    }
207|    let end: number | undefined;
208|    if (endSec !== undefined) {
209|      if (typeof endSec !== "number" || !Number.isFinite(endSec)) {
210|        throw new Error(`track ${id} endSec must be a finite number`);
211|      }
212|      if (endSec <= start) {
213|        throw new Error(`track ${id} endSec must be above startSec`);
214|      }
215|      // durationSec rounds to 1 decimal, so allow that slack on the end.
216|      if (endSec - start > durationSec + 0.051) {
217|        throw new Error(`track ${id} endSec must not pass startSec + durationSec`);
218|      }
219|      end = endSec;
220|    }
221|    let loops = true;
222|    if (loop !== undefined) {
223|      if (typeof loop !== "boolean") throw new Error(`track ${id} loop must be a boolean`);
224|      loops = loop;
225|    }
226|    let only = false;
227|    if (playlistOnly !== undefined) {
228|      if (typeof playlistOnly !== "boolean") {
229|        throw new Error(`track ${id} playlistOnly must be a boolean`);
230|      }
231|      only = playlistOnly;
232|    }
233|    let trackSource: TrackSource | undefined;
234|    if (source !== undefined) {
235|      if (!isOneOf(source, SOURCES)) {
236|        throw new Error(`track ${id} source must be generated, jamendo, or recording`);
237|      }
238|      trackSource = source;
239|    }
240|    const credit: { artist?: string; composer?: string; license?: string; attribution?: string } = {};
241|    const pairs = [
242|      ["artist", artist],
243|      ["composer", composer],
244|      ["license", license],
245|      ["attribution", attribution],
246|    ] as const;
247|    for (const [key, value] of pairs) {
248|      if (value === undefined) continue;
249|      if (!isNonEmptyString(value)) throw new Error(`track ${id} ${key} must be a non-empty string`);
250|      credit[key] = value;
251|    }
252|    if (sourceUrl !== undefined && (typeof sourceUrl !== "string" || !sourceUrl.startsWith("https://"))) {
253|      throw new Error(`track ${id} sourceUrl must be an https URL`);
254|    }
255|    return {
256|      id,
257|      src,
258|      title,
259|      playlistOnly: only,
260|      emotion,
261|      vector,
262|      intensity,
263|      tempo,
264|      durationSec,
265|      startSec: start,
266|      gainDb: gain,
267|      ...(end === undefined ? {} : { endSec: end }),
268|      loop: loops,
269|      soundtrack,
270|      style,
271|      ...credit,
272|      ...(trackSource === undefined ? {} : { source: trackSource }),
273|      ...(sourceUrl === undefined ? {} : { sourceUrl }),
274|    };
275|  }
