1|// Web Audio engine behind AmbienceController. One lazily created
2|// AudioContext; loops run through BufferSource loop, so fades on the
3|// audio clock still finish in a background tab.
4|import type { AmbienceEngine, AmbienceVoice } from "./ambience-controller";
5|import type { AmbienceSource } from "@/core/ambience";
6|
7|let shared: AudioContext | null = null;
8|const decoded = new Map<string, Promise<AudioBuffer>>();
9|
10|function context(): AudioContext {
11|  if (!shared) shared = new AudioContext();
12|  return shared;
13|}
14|
15|// First source canPlayType rates "probably" or "maybe", else the first.
16|function pickSource(sources: AmbienceSource[]): AmbienceSource | null {
17|  if (sources.length === 0) return null;
18|  try {
19|    const probe = new Audio();
20|    return (
21|      sources.find((source) => {
22|        const verdict = probe.canPlayType(source.type);
23|        return verdict === "probably" || verdict === "maybe";
24|      }) ?? sources[0]!
25|    );
26|  } catch {
27|    return sources[0]!;
28|  }
29|}
30|
31|export class WebAmbienceEngine implements AmbienceEngine {
32|  private createContext: () => AudioContext;
33|
34|  constructor(options: { context?: () => AudioContext } = {}) {
35|    this.createContext = options.context ?? context;
36|  }
37|
38|  load(sources: AmbienceSource[]): Promise<AudioBuffer> {
39|    const ctx = this.createContext();
40|    const picked = pickSource(sources);
41|    if (!picked) return Promise.reject(new Error("no ambience sources"));
42|    let pending = decoded.get(picked.src);
43|    if (!pending) {
44|      pending = (async () => {
45|        const response = await fetch(picked.src);
46|        if (!response.ok) throw new Error(`ambience fetch failed: ${picked.src}`);
47|        return ctx.decodeAudioData(await response.arrayBuffer());
48|      })();
49|      decoded.set(picked.src, pending);
50|      pending.then(null, () => void decoded.delete(picked.src));
51|    }
52|    return pending;
53|  }
54|
55|  start(handle: unknown, gain: number, fadeSec: number): AmbienceVoice {
56|    const ctx = this.createContext();
57|    const source = ctx.createBufferSource();
58|    source.buffer = handle as AudioBuffer;
59|    source.loop = true;
60|    // One curve per node, so a later event never overlaps an active curve.
61|    const fadeIn = ctx.createGain();
62|    const fadeOut = ctx.createGain();
63|    const level = ctx.createGain();
64|    const at = ctx.currentTime;
65|    fadeOut.gain.value = 1;
66|    level.gain.value = gain;
67|    if (fadeSec > 0) {
68|      // Sine in, matching the outgoing voice's cosine out for equal power.
69|      fadeIn.gain.value = 0;
70|      const curve = new Float32Array(32).map((_, i) => Math.sin(((i / 31) * Math.PI) / 2));
71|      try {
72|        fadeIn.gain.setValueCurveAtTime(curve, at, fadeSec);
73|      } catch {
74|        fadeIn.gain.value = 1;
75|      }
76|    } else {
77|      fadeIn.gain.value = 1;
78|    }
79|    source.connect(fadeIn);
80|    fadeIn.connect(fadeOut);
81|    fadeOut.connect(level);
82|    level.connect(ctx.destination);
83|    source.start(at);
84|    let stopped = false;
85|    const disconnect = () => {
86|      source.disconnect();
87|      fadeIn.disconnect();
88|      fadeOut.disconnect();
89|      level.disconnect();
90|    };
91|    return {
92|      ramp(next: number, sec: number) {
93|        // Level never holds a curve, so cancel + anchor + ramp cannot overlap one.
94|        const now = ctx.currentTime;
95|        try {
96|          level.gain.cancelScheduledValues(now);
97|          level.gain.setValueAtTime(level.gain.value, now);
98|          level.gain.linearRampToValueAtTime(next, now + Math.max(0, sec));
99|        } catch {
100|          level.gain.value = next;
101|        }
102|      },
103|      stop(sec: number) {
104|        if (stopped) return;
105|        stopped = true;
106|        const now = ctx.currentTime;
107|        const span = Math.max(0, sec);
108|        if (span <= 0) {
109|          try {
110|            source.stop(now);
111|          } catch {
112|            // Already stopped.
113|          }
114|          disconnect();
115|          return;
116|        }
117|        // Cosine out over the same span: sin^2 + cos^2 keeps equal power.
118|        const curve = new Float32Array(32).map((_, i) => Math.cos(((i / 31) * Math.PI) / 2));
119|        try {
120|          fadeOut.gain.setValueCurveAtTime(curve, now, span);
121|        } catch {
122|          fadeOut.gain.value = 0;
123|        }
124|        source.onended = () => disconnect();
125|        try {
126|          source.stop(now + span);
127|        } catch {
128|          // Already stopped; onended still disconnects.
129|        }
130|      },
131|    };
132|  }
133|
134|  unlock(): Promise<void> {
135|    return this.createContext().resume().then(() => undefined);
136|  }
137|}

