102|function parseLabels(json: unknown): { tracks: ExportTrack[]; segments: ExportSegment[] } {
103|  if (!isRecord(json)) throw new Error("labels export must be an object");
104|  if (json.schemaVersion !== 2) {
105|    throw new Error(`labels export schemaVersion must be 2, got ${String(json.schemaVersion)}`);
106|  }
107|  if (!Array.isArray(json.tracks)) throw new Error("labels export tracks must be an array");
108|  if (!Array.isArray(json.segments)) throw new Error("labels export segments must be an array");
109|  const tracks = json.tracks.map((entry, i) => {
110|    if (!isRecord(entry)) throw new Error(`labels track ${i} must be an object`);
111|    const trackId = reqString(entry, "trackId", `labels track ${i}`);
112|    const status = entry.status;
113|    if (!isStatus(status)) {
114|      throw new Error(`labels track ${trackId} has unknown status ${String(status)}`);
115|    }
116|    const style = optString(entry, "style", `labels track ${trackId}`);
117|    return { trackId, status, ...(style === undefined ? {} : { style }) };
118|  });
119|  const segments = json.segments.map((entry, i) => {
120|    if (!isRecord(entry)) throw new Error(`labels segment ${i} must be an object`);
121|    const trackId = reqString(entry, "trackId", `labels segment ${i}`);
122|    const segmentId = reqString(entry, "segmentId", `labels segment ${i}`);
123|    const what = `segment ${segmentId}`;
124|    const startSec = reqFinite(entry, "startSec", what);
125|    const endSec = reqFinite(entry, "endSec", what);
126|    if (startSec < 0 || endSec <= startSec) throw new Error(`${what} needs 0 <= startSec < endSec`);
127|    const primary = entry.primary;
128|    if (!isEmotion(primary)) throw new Error(`${what} primary must be one of the 8 emotion ids`);
129|    let vector: Vector8 | undefined;
130|    if (entry.vector !== undefined) {
131|      if (!isRecord(entry.vector)) throw new Error(`${what} vector must be an object`);
132|      const out = {} as Record<EmotionId, number>;
133|      for (const id of EMOTIONS) {
134|        const raw = entry.vector[id];
135|        if (raw === undefined) {
136|          out[id] = 0;
137|        } else {
138|          if (typeof raw !== "number" || !Number.isFinite(raw)) {
139|            throw new Error(`${what} vector ${id} must be a finite number`);
140|          }
141|          out[id] = Math.round(Math.min(1, Math.max(0, raw)) * 1000) / 1000;
142|        }
143|      }
144|      vector = out as Vector8;
145|    }
146|    const level = (key: string): number => {
147|      const n = reqFinite(entry, key, what);
148|      if (!Number.isInteger(n) || n < 1 || n > 5) throw new Error(`${what} ${key} must be an integer 1..5`);
149|      return n;
150|    };
151|    return {
152|      trackId,
153|      segmentId,
154|      startSec,
155|      endSec,
156|      primary,
157|      ...(vector === undefined ? {} : { vector }),
158|      intensity: level("intensity"),
159|      tempo: level("tempo"),
160|    };
161|  });
162|  return { tracks, segments };
