55|  start(handle: unknown, gain: number, fadeSec: number): AmbienceVoice {
56|    const ctx = this.createContext();
57|    const source = ctx.createBufferSource();
58|    source.buffer = handle as AudioBuffer;
59|    source.loop = true;
60|    // One curve per node, so a later event never overlaps an active curve.
61|    const fadeIn = ctx.createGain();
62|    const fadeOut = ctx.createGain();
63|    const level = ctx.createGain();
64|    const at = ctx.currentTime;
65|    fadeOut.gain.value = 1;
66|    level.gain.value = gain;
67|    if (fadeSec > 0) {
68|      // Sine in, matching the outgoing voice's cosine out for equal power.
69|      fadeIn.gain.value = 0;
70|      const curve = new Float32Array(32).map((_, i) => Math.sin(((i / 31) * Math.PI) / 2));
71|      try {
72|        fadeIn.gain.setValueCurveAtTime(curve, at, fadeSec);
73|      } catch {
74|        fadeIn.gain.value = 1;
75|      }
76|    } else {
77|      fadeIn.gain.value = 1;
78|    }
79|    source.connect(fadeIn);
80|    fadeIn.connect(fadeOut);
81|    fadeOut.connect(level);
82|    level.connect(ctx.destination);
83|    source.start(at);
84|    let stopped = false;
85|    const disconnect = () => {
86|      source.disconnect();
87|      fadeIn.disconnect();
88|      fadeOut.disconnect();
89|      level.disconnect();
90|    };
