93|        // Level never holds a curve, so cancel + anchor + ramp cannot overlap one.
94|        const now = ctx.currentTime;
95|        try {
96|          level.gain.cancelScheduledValues(now);
97|          level.gain.setValueAtTime(level.gain.value, now);
98|          level.gain.linearRampToValueAtTime(next, now + Math.max(0, sec));
99|        } catch {
100|          level.gain.value = next;
101|        }
102|      },
103|      stop(sec: number) {
104|        if (stopped) return;
105|        stopped = true;
106|        const now = ctx.currentTime;
107|        const span = Math.max(0, sec);
108|        if (span <= 0) {
109|          try {
110|            source.stop(now);
111|          } catch {
112|            // Already stopped.
113|          }
114|          disconnect();
115|          return;
116|        }
117|        // Cosine out over the same span: sin^2 + cos^2 keeps equal power.
118|        const curve = new Float32Array(32).map((_, i) => Math.cos(((i / 31) * Math.PI) / 2));
119|        try {
120|          fadeOut.gain.setValueCurveAtTime(curve, now, span);
121|        } catch {
122|          fadeOut.gain.value = 0;
123|        }
124|        source.onended = () => disconnect();
125|        try {
126|          source.stop(now + span);
127|        } catch {
128|          // Already stopped; onended still disconnects.
129|        }
130|      },
131|    };
132|  }
