165|function parseLibrary(json: unknown): Library {
166|  if (!isRecord(json)) throw new Error("library must be an object");
167|  if (json.version !== 1) throw new Error(`library version must be 1, got ${String(json.version)}`);
168|  if (!Array.isArray(json.styles)) throw new Error("library styles must be an array");
169|  if (!Array.isArray(json.soundtracks)) throw new Error("library soundtracks must be an array");
170|  if (!Array.isArray(json.playlists ?? [])) throw new Error("library playlists must be an array");
171|  const soundtracks = json.soundtracks.map((entry, i) => {
172|    if (!isRecord(entry)) throw new Error(`library soundtrack ${i} must be an object`);
173|    const credit = optString(entry, "credit", `library soundtrack ${entry.id ?? i}`);
174|    return {
175|      id: reqString(entry, "id", `library soundtrack ${i}`),
176|      name: reqString(entry, "name", `library soundtrack ${i}`),
177|      style: reqString(entry, "style", `library soundtrack ${i}`),
178|      ...(credit === undefined ? {} : { credit }),
179|    };
180|  });
181|  if (!isRecord(json.entries)) throw new Error("library entries must be an object");
182|  const entries: Record<string, LibraryEntry> = {};
183|  for (const [trackId, raw] of Object.entries(json.entries)) {
184|    if (!isRecord(raw)) throw new Error(`library entry ${trackId} must be an object`);
185|    const what = `library entry ${trackId}`;
186|    const durationSec = reqFinite(raw, "durationSec", what);
187|    if (durationSec <= 0) throw new Error(`${what} durationSec must be positive`);
188|    const gainDb = raw.gainDb;
189|    if (gainDb !== undefined && (typeof gainDb !== "number" || !Number.isFinite(gainDb))) {
190|      throw new Error(`${what} gainDb must be a finite number`);
191|    }
192|    const noDerivatives = raw.noDerivatives;
193|    if (noDerivatives !== undefined && typeof noDerivatives !== "boolean") {
194|      throw new Error(`${what} noDerivatives must be a boolean`);
195|    }
196|    const source = raw.source;
197|    if (source !== undefined && source !== "generated" && source !== "jamendo" && source !== "recording") {
198|      throw new Error(`${what} source must be generated, jamendo, or recording`);
199|    }
200|    entries[trackId] = {
201|      src: reqString(raw, "src", what),
202|      soundtrack: reqString(raw, "soundtrack", what),
203|      durationSec,
204|      title: reqString(raw, "title", what),
205|      ...(noDerivatives === undefined ? {} : { noDerivatives }),
206|      ...(gainDb === undefined ? {} : { gainDb }),
207|      ...(source === undefined ? {} : { source }),
208|    };
209|    for (const key of ["composer", "artist", "license", "attribution", "sourceUrl"] as const) {
210|      const value = optString(raw, key, what);
211|      if (value !== undefined) entries[trackId]![key] = value;
212|    }
213|  }
214|  const extraTracks = json.extraTracks ?? [];
215|  if (!Array.isArray(extraTracks)) throw new Error("library extraTracks must be an array");
216|  return {
217|    styles: json.styles as StyleInfo[],
218|    soundtracks,
219|    entries,
220|    extraTracks,
221|    playlists: (json.playlists ?? []) as Playlist[],
222|  };
223|}
224|
225|function oneHot(primary: EmotionId): Vector8 {
226|  const out = {} as Record<EmotionId, number>;
227|  for (const id of EMOTIONS) out[id] = id === primary ? 1 : 0;
228|  return out as Vector8;
229|}
