231|export function labelsToManifest(
232|  labelsJson: unknown,
233|  libraryJson: unknown,
234|  opts: { reviewedOnly?: boolean } = {},
235|): { manifest: ConvertedManifest; warnings: string[] } {
236|  const labels = parseLabels(labelsJson);
237|  const library = parseLibrary(libraryJson);
238|  const warnings: string[] = [];
239|  const styleOf = new Map(library.soundtracks.map((s) => [s.id, s.style]));
240|  const seen = new Set(labels.tracks.map((t) => t.trackId));
241|  const segmentsByTrack = new Map<string, ExportSegment[]>();
242|  for (const seg of labels.segments) {
243|    if (!seen.has(seg.trackId)) {
244|      warnings.push(`skip segment ${seg.segmentId}: unknown export track ${seg.trackId}`);
245|      continue;
246|    }
247|    const list = segmentsByTrack.get(seg.trackId) ?? [];
248|    list.push(seg);
249|    segmentsByTrack.set(seg.trackId, list);
250|  }
251|  const tracks: ManifestTrack[] = [];
252|  for (const exp of labels.tracks) {
253|    if (exp.status === "discarded") {
254|      warnings.push(`skip ${exp.trackId}: discarded`);
255|      continue;
256|    }
257|    if (opts.reviewedOnly && exp.status === "todo") {
258|      warnings.push(`skip ${exp.trackId}: not reviewed`);
259|      continue;
260|    }
261|    const entry = library.entries[exp.trackId];
262|    if (!entry) {
263|      warnings.push(`skip ${exp.trackId}: no library entry`);
264|      continue;
265|    }
266|    const style = styleOf.get(entry.soundtrack);
267|    if (style === undefined) {
268|      warnings.push(`skip ${exp.trackId}: unknown soundtrack ${entry.soundtrack}`);
269|      continue;
270|    }
271|    if (exp.style !== undefined && exp.style !== style) {
272|      warnings.push(
273|        `skip ${exp.trackId}: export style ${exp.style} differs from soundtrack style ${style}`,
274|      );
275|      continue;
276|    }
277|    const segs = segmentsByTrack.get(exp.trackId) ?? [];
278|    if (segs.length === 0) {
279|      warnings.push(`skip ${exp.trackId}: no segments`);
280|      continue;
281|    }
282|    const provisional = exp.status === "todo";
283|    if (entry.noDerivatives === true) {
284|      const longest = segs.reduce((a, b) => (b.endSec - b.startSec > a.endSec - a.startSec ? b : a));
285|      if (segs.length > 1) {
286|        warnings.push(`ND ${exp.trackId}: whole file keeps longest segment ${longest.segmentId}`);
287|      }
288|      tracks.push(convertSegment(exp.trackId, exp.trackId, longest, entry, style, provisional, true));
289|      continue;
290|    }
291|    for (const seg of segs) {
292|      tracks.push(
293|        convertSegment(
294|          segs.length === 1 ? exp.trackId : seg.segmentId,
295|          exp.trackId,
296|          seg,
297|          entry,
298|          style,
299|          provisional,
300|          false,
301|        ),
302|      );
303|    }
304|  }
305|  tracks.sort((a, b) => (a.soundtrack < b.soundtrack ? -1 : a.soundtrack > b.soundtrack ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
306|  for (const raw of library.extraTracks) {
307|    if (!isRecord(raw)) throw new Error("library extraTracks entries must be objects");
308|    // parseManifest below checks the full shape before anything is written.
309|    tracks.push(raw as unknown as ManifestTrack);
310|  }
311|  const manifest: ConvertedManifest = {
312|    version: 3,
313|    styles: library.styles,
314|    soundtracks: library.soundtracks,
315|    tracks,
316|    playlists: library.playlists,
317|  };
318|  parseManifest(manifest);
319|  return { manifest, warnings };
320|}
321|
322|function convertSegment(
323|  id: string,
324|  labelId: string,
325|  seg: ExportSegment,
326|  entry: LibraryEntry,
327|  style: string,
328|  provisional: boolean,
329|  whole: boolean,
330|): ManifestTrack {
331|  const vector = seg.vector ?? oneHot(seg.primary);
332|  const intensity = Math.round(((seg.intensity - 1) / 4) * 1000) / 1000;
333|  const tempo = Math.round(((seg.tempo - 1) / 4) * 1000) / 1000;
334|  const endBeforeFile = seg.endSec < entry.durationSec - 0.5;
335|  const startSec = !whole && seg.startSec > 0 ? seg.startSec : undefined;
336|  const endSec = !whole && endBeforeFile ? seg.endSec : undefined;
337|  const durationSec = Math.round(((endSec ?? entry.durationSec) - (startSec ?? 0)) * 10) / 10;
338|  return {
339|    id,
340|    labelId,
341|    ...(provisional ? { provisional: true as const } : {}),
342|    src: entry.src,
343|    title: entry.title,
344|    emotion: seg.primary,
345|    vector,
346|    intensity,
347|    tempo,
348|    durationSec,
349|    ...(startSec === undefined ? {} : { startSec }),
350|    ...(entry.gainDb !== undefined && entry.gainDb !== 0 ? { gainDb: entry.gainDb } : {}),
351|    ...(endSec === undefined ? {} : { endSec }),
352|    loop: true,
353|    soundtrack: entry.soundtrack,
354|    style,
355|    ...(entry.composer === undefined ? {} : { composer: entry.composer }),
356|    ...(entry.artist === undefined ? {} : { artist: entry.artist }),
357|    ...(entry.license === undefined ? {} : { license: entry.license }),
358|    ...(entry.attribution === undefined ? {} : { attribution: entry.attribution }),
359|    ...(entry.sourceUrl === undefined ? {} : { sourceUrl: entry.sourceUrl }),
360|    ...(entry.source === undefined ? {} : { source: entry.source }),
361|  };
362|}
363|
364|const USAGE = "usage: build:music <labels.json> <library.json> [--reviewed-only] [--out manifest.json]";
365|
366|function main(): void {
367|  const args = process.argv.slice(2);
368|  const reviewedOnly = args.includes("--reviewed-only");
369|  const outFlag = args.indexOf("--out");
370|  let out: string | undefined;
371|  if (outFlag !== -1) {
372|    out = args[outFlag + 1];
373|    if (out === undefined || out.startsWith("--")) throw new Error(USAGE);
374|  }
375|  for (const arg of args) {
376|    if (arg.startsWith("--") && arg !== "--reviewed-only" && arg !== "--out") {
377|      throw new Error(`unknown flag ${arg}\n${USAGE}`);
378|    }
379|  }
380|  const inputs = args.filter(
381|    (arg, i) => !arg.startsWith("--") && (outFlag === -1 || i !== outFlag + 1),
382|  );
383|  if (inputs.length !== 2 || inputs[0] === undefined || inputs[1] === undefined) throw new Error(USAGE);
384|  const labels = JSON.parse(readFileSync(inputs[0], "utf8"));
385|  const library = JSON.parse(readFileSync(inputs[1], "utf8"));
386|  const { manifest, warnings } = labelsToManifest(labels, library, { reviewedOnly });
387|  for (const warning of warnings) console.error(warning);
388|  const json = `${JSON.stringify(manifest, null, 2)}\n`;
389|  if (out !== undefined) {
390|    writeFileSync(out, json);
391|    console.error(`wrote ${manifest.tracks.length} tracks to ${out}`);
392|  } else {
393|    process.stdout.write(json);
394|  }
395|}
