1|import { describe, expect, it } from "vitest";
2|import { WebAmbienceEngine } from "./ambience-engine";
3|
4|// Minimal fake AudioContext. Fake params record events and throw when an
5|// event lands inside an active curve's span on the same param, like Chrome.
6|class FakeParam {
7|  value = 0;
8|  curves: Array<{ start: number; end: number; values: number[] }> = [];
9|  ops: string[] = [];
10|
11|  private active(at: number): boolean {
12|    return this.curves.some((curve) => at >= curve.start && at < curve.end);
13|  }
14|
15|  private overlap(op: string): never {
16|    const error = new Error(`${op} overlaps an active curve`);
17|    error.name = "NotSupportedError";
18|    throw error;
19|  }
20|
21|  cancelScheduledValues(at: number): void {
22|    this.ops.push("cancel");
23|    this.curves = this.curves.filter((curve) => curve.start < at);
24|  }
25|
26|  setValueAtTime(value: number, at: number): void {
27|    if (this.active(at)) this.overlap("setValueAtTime");
28|    this.value = value;
29|    this.ops.push("set");
30|  }
31|
32|  linearRampToValueAtTime(value: number, at: number): void {
33|    if (this.active(at)) this.overlap("linearRamp");
34|    this.value = value;
35|    this.ops.push("ramp");
36|  }
37|
38|  setValueCurveAtTime(curve: Float32Array, at: number, duration: number): void {
39|    if (this.active(at)) this.overlap("setValueCurveAtTime");
40|    this.curves.push({ start: at, end: at + duration, values: Array.from(curve) });
41|    this.ops.push("curve");
42|  }
43|}
44|
45|interface FakeGain {
46|  gain: FakeParam;
47|  disconnected: boolean;
48|  connect(): void;
49|  disconnect(): void;
50|}
51|
52|interface FakeSource {
53|  buffer: unknown;
54|  loop: boolean;
55|  onended: (() => void) | null;
56|  stops: number[];
57|  disconnected: boolean;
58|  connect(): void;
59|  disconnect(): void;
60|  start(): void;
61|  stop(at: number): void;
62|}
63|
64|function fakeContext() {
65|  const ctx = {
66|    currentTime: 0,
67|    destination: {},
68|    gains: [] as FakeGain[],
69|    sources: [] as FakeSource[],
70|    createGain(): FakeGain {
71|      const node: FakeGain = {
72|        gain: new FakeParam(),
73|        disconnected: false,
74|        connect() {},
75|        disconnect() {
76|          node.disconnected = true;
77|        },
78|      };
79|      ctx.gains.push(node);
80|      return node;
81|    },
82|    createBufferSource(): FakeSource {
83|      const source: FakeSource = {
84|        buffer: null,
85|        loop: false,
86|        onended: null,
87|        stops: [],
88|        disconnected: false,
89|        connect() {},
90|        disconnect() {
91|          source.disconnected = true;
92|        },
93|        start() {},
94|        stop(at: number) {
95|          source.stops.push(at);
96|        },
97|      };
98|      ctx.sources.push(source);
99|      return source;
100|    },
101|  };
102|  return ctx;
103|}
104|
105|type FakeCtx = ReturnType<typeof fakeContext>;
106|
107|function engineWith(ctx: FakeCtx): WebAmbienceEngine {
108|  return new WebAmbienceEngine({ context: () => ctx as unknown as AudioContext });
